-- Anexos e backups ficam no próprio MySQL (o disco do app pode ser recriado a cada deploy).
CREATE TABLE IF NOT EXISTS arquivos(caminho VARCHAR(255) PRIMARY KEY,mime VARCHAR(120) NOT NULL,tamanho BIGINT NOT NULL,conteudo LONGBLOB NOT NULL,criado_em VARCHAR(40) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS backups(nome VARCHAR(120) PRIMARY KEY,criado_em VARCHAR(40) NOT NULL,conteudo LONGBLOB NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS app_meta(k VARCHAR(64) PRIMARY KEY,v VARCHAR(255) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
